const transporter = nodemailer.createTransport({
    pool: true,
    maxConnections: 1,
    host: "esai-mpq.mitchellplastics.com", 
    port: 25,
    secure: false,       
    ignoreTLS: true,      
    connectionTimeout: 1000000, 
    greetingTimeout: 1000000,   
    timeout: 1000000, 
    tls: {
        rejectUnauthorized: false 
    }
});

const mailOptions = {
    from: "mpq.lpaboard@mitchellplastics.com", 
    to: 'ian.barcenas@mitchellplastics.com',
    subject: "Reporte Diario Tablero LPA",
    html: msg.payload
};


node.status({fill:"blue", shape:"dot", text:"Esperando saludo del servidor ..."});

transporter.sendMail(mailOptions)
    .then(info => {
        node.status({fill:"green", shape:"dot", text:"Enviado correctamente"});
        node.send(msg);
    })
