let registros = msg.payload;
var hoy = new Date();
var pasado = new Date()
pasado = pasado.setDate(hoy.getDate() - 4)
var pasado_formato = new Date(pasado)
let total = 0;
let htmlMensaje2 = '';
let htmlMensaje3 = `<h2 style="color:red;">Auditores que NO hicieron su auditoría esta semana:</h2>`
var JEflag = 0; // Jonathan-Pinto flag 
var OSflag = 0; // Omar-Scott flag
let ADflag = 0; // Anahi-Diego flag
var JERegistros = 0;
var OSRegistros = 0;
let ADRegistros = 0;
let auditoresPares = ['Anahi Aguilar', 'Diego Mandujano', 'Scott Coulter', 'Omar Sanchez', 'Jonathan Kebick', 'Eduardo Pinto']

for (let index = 0; index < registros.length; index++) {
    let encontrado = 0;
    let registroEncontrado = registros[index];

    if(registroEncontrado.registros > 0){
        let maximo = 0;
        let diasAuditoria = registros[index].dias.split(',');

        if(diasAuditoria == "semanal"){
            maximo = 1;
        } else {
            maximo = diasAuditoria.length;
        }

        total += Number(registroEncontrado.registros);
        if(registroEncontrado.nombre == 'Jonathan Kebick' || registroEncontrado.nombre == 'Eduardo Pinto'){
            JERegistros += Number(registroEncontrado.registros); 
            JEflag = 1;
        } else if (registroEncontrado.nombre == 'Scott Coulter' || registroEncontrado.nombre == 'Omar Sanchez'){
            OSRegistros += Number(registroEncontrado.registros);
            OSflag = 1;
        } else if (registroEncontrado.nombre == 'Anahi Aguilar' || registroEncontrado.nombre == 'Diego Mandujano') {
            ADRegistros += Number(registroEncontrado.registros);
            ADflag = 1;
        } else{
            htmlMensaje2 += `<li>${registroEncontrado.nombre} : <span style="color: ${registroEncontrado.registros >= maximo ? 'green' : 'red'};">${registroEncontrado.registros} / ${maximo}</span></li>`
        }
        encontrado = 1;
    } 
    if(encontrado == 0 && !(auditoresPares.includes(registros[index].nombre))){
        htmlMensaje3 += `<li>${registros[index].nombre}</li>`
    }

}
if(JERegistros > 0){ 
    htmlMensaje2 += `<li>Jonathan Kebick/Eduardo Pinto:<span style="color: 'green';"> ${JERegistros} / 1</span></li>`
} else {
    htmlMensaje3 += `<li>Jonathan Kebick/Eduardo Pinto</li>`
}
if(OSRegistros > 0){
    htmlMensaje2 += `<li>Scott Coulter/Omar Sanchez:<span style="color: 'green';"> ${OSRegistros} / 1</span> </li>`
}else {
    htmlMensaje3 += `<li>Scott Coulter/Omar Sanchez</li>`
}
if(ADRegistros > 0){
    htmlMensaje2 += `<li>Anahí Aguilar/Diego Mandujano:<span style="color: 'green';"> ${ADRegistros} / 1 </span></li>`
} else {
    htmlMensaje3 += `<li>Anahí Aguilar/Diego Mandujano</li>`
}
JEflag = 0;
OSflag = 0;
ADflag = 0;

